import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> [side, price, qty_remaining, arrival, active]
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    arrival_counter = 0

    def clean_buy_heap():
        while buy_heap:
            negprice, arr, oid = buy_heap[0]
            info = orders_info.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, arr, oid = sell_heap[0]
            info = orders_info.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info[4] and info[2] > 0:
                info[4] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        arrival = arrival_counter
        arrival_counter += 1

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                sp, sarr, sid = sell_heap[0]
                if price is not None and sp > price:
                    break
                # match
                sinfo = orders_info[sid]
                trade_qty = min(remaining, sinfo[2])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sinfo[2] -= trade_qty
                if sinfo[2] <= 0:
                    heapq.heappop(sell_heap)
                    sinfo[4] = False
            if typ == 'limit' and remaining > 0:
                orders_info[oid] = [side, price, remaining, arrival, True]
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                if remaining > 0:
                    # discard remainder, mark as inactive/filled if needed (no need since not in book)
                    orders_info[oid] = [side, price, 0, arrival, False]
                else:
                    orders_info[oid] = [side, price, 0, arrival, False]
        else:  # sell
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                negbp, barr, bid = buy_heap[0]
                bp = -negbp
                if price is not None and bp < price:
                    break
                binfo = orders_info[bid]
                trade_qty = min(remaining, binfo[2])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                binfo[2] -= trade_qty
                if binfo[2] <= 0:
                    heapq.heappop(buy_heap)
                    binfo[4] = False
            if typ == 'limit' and remaining > 0:
                orders_info[oid] = [side, price, remaining, arrival, True]
                heapq.heappush(sell_heap, (price, arrival, oid))
            else:
                if remaining > 0:
                    orders_info[oid] = [side, price, 0, arrival, False]
                else:
                    orders_info[oid] = [side, price, 0, arrival, False]

    return trades

